import {esc,uid,sha256} from './core.js';
import {companionAPI as api,isCompanion,decode64,encode64} from './companion-client.js';
export async function validateDebugRecord(e){
 const s=e?.session;if(e?.format!=='probe-debug-session-v1'||!s||typeof s.id!=='string'||typeof s.label!=='string'||!Array.isArray(s.dumps)||s.dumps.length>1000||!Array.isArray(s.events)||s.events.length>5000||!Array.isArray(s.transcript)||s.transcript.length>20000)throw Error('Invalid debugger record.');
 if(await sha256(new TextEncoder().encode(JSON.stringify(s)))!==e.recordHash)throw Error('Debugger record hash does not match.');let size=0;
 for(const d of s.dumps){if(typeof d.dataBase64!=='string'||d.dataBase64.length>1398104||!Number.isInteger(d.size)||d.size<0||d.size>1048576)throw Error('Invalid memory dump.');const bytes=decode64(d.dataBase64);size+=bytes.length;if(size>8388608||bytes.length!==d.size||await sha256(bytes)!==d.sha256)throw Error('Memory dump hash does not match.');}return e;
}
export function createDebugUI(ui){
 const {button,tag,showDialog,field,area,notify}=ui;const request=ui.api||api;let status=null,message='',selected='',busy=false,pollTimer=null,lastReported='';
 const records=()=>ui.project()?.debugSessions?.filter(s=>s.deviceId===ui.project().deviceId)||[];
 const current=()=>status?.sessions.find(s=>s.id===selected&&s.projectId===ui.project()?.id&&s.deviceId===ui.project()?.deviceId);
 const options=()=>status?.profiles.map(p=>`<option value="${esc(p.id)}">${esc(p.label)} · unverified</option>`).join('')||'';
 function view(){const p=ui.project(),s=current(),sessions=status?.sessions.filter(x=>x.projectId===p.id&&x.deviceId===p.deviceId)||[],active=status?.active;return `<div id="debug-live"><section class="panel spaced"><div class="panel-head"><h2>Debugger bench</h2>${tag(s?.targetState||'LOCAL COMPANION')}</div><div class="panel-body"><div class="row between wrap"><div><strong>OpenOCD + GDB / MI</strong><p class="muted smalltext spaced">ARM profiles · explicit execution control · preserved memory evidence</p></div><div class="row wrap">${button('Local setup / pair','scan-setup','small')}${button('Refresh debugger','debug-refresh','small')}${button('Attach target','debug-attach','primary','',!status||busy||status?.busy||active?'disabled':'')}${button('Import session','debug-import','small','upload')}</div></div>${message?`<p class="notice spaced" role="status">${esc(message)}</p>`:''}${!status?'<p class="notice spaced">Launch the companion with an operator-reviewed profile file, then pair and refresh. Hosted PROBE reviews imported sessions. Physical probe/target acceptance remains open.</p>':`<p class="muted smalltext spaced">${esc(Object.entries(status.versions).map(([k,v])=>k+': '+(v.available?v.version:v.error)).join(' · '))}</p>${active&&(!s||active.id!==s.id)?`<p class="notice spaced">An active session belongs to ${esc(active.label)}. Select its project/device to operate it, or stop the companion locally. No automatic attach or command replay.</p>`:''}`}${sessions.length?`<label class="field spaced">Acquisition sessions<select id="debug-session">${sessions.map(x=>`<option value="${x.id}" ${x.id===selected?'selected':''}>${esc(x.label)} · ${esc(x.status)}</option>`).join('')}</select></label>`:''}${s?`<div class="baseline-row spaced"><h3>${esc(s.label)}</h3><p class="smalltext spaced">${esc(s.status)} · last reported ${esc(lastReported)} · target ${esc(s.targetState)} · ${esc(s.startedAt)}</p><p class="scope-text spaced">${esc(s.conditions)}</p>${s.error?`<p class="notice spaced">${esc(s.error)}</p>`:''}<div class="row wrap spaced">${['status','halt','resume','step','registers','backtrace','memory','breakpoint','watchpoint','symbols','detach'].map(op=>button(({status:'Read state',halt:'Halt',resume:'Resume',step:'Step instruction',registers:'Read registers',backtrace:'Backtrace',memory:'Read memory',breakpoint:'Hardware break',watchpoint:'Hardware watch',symbols:'Load ELF symbols',detach:'Detach'})[op],'debug-op','small', '',`data-id="${op}" ${s.status!=='connected'||busy||status?.busy||(!['status','halt','detach'].includes(op)&&s.targetState!=='stopped')?'disabled':''}`)).join('')}</div><div class="row wrap spaced">${button('Preserve snapshot','debug-preserve','primary')}${button('Export session JSON','debug-export','small','download')}</div><p class="muted smalltext spaced">Snapshots include acquisition context, transcript, registers and dumps. Exported hashes check consistency; they do not authenticate the collector.</p></div><div class="two-col spaced"><div><h3>Registers</h3><pre class="code-preview">${esc(s.registers.map(r=>r.name.padEnd(10)+' '+r.value).join('\n')||'Read registers while stopped.')}</pre></div><div><h3>Stack frames</h3><pre class="code-preview">${esc(JSON.stringify(s.backtrace,null,2))}</pre></div></div><h3 class="spaced">Memory & breakpoints</h3>${s.dumps.map(d=>`<p class="smalltext spaced mono">${esc(d.address)} · ${d.size} bytes · ${esc(d.sha256)}</p>`).join('')||'<p class="muted smalltext">No complete memory reads yet.</p>'}${s.lastStop?`<p class="notice spaced">Last stop: ${esc(s.lastStop.reason)} · ${esc(s.lastStop.at)} · ${esc(s.lastStop.frame?.addr||'address unavailable')}</p>`:''}${s.breakpoints.map(b=>`<div class="baseline-row spaced"><div class="row between wrap"><strong>#${esc(b.number)} ${esc(b.type)} · ${esc(b.address)}</strong><div class="row">${button('Configure','debug-configure','small','',`data-id="${esc(b.number)}" ${busy||status.busy||s.targetState!=='stopped'?'disabled':''}`)}${button('Remove','debug-remove','small','',`data-id="${esc(b.number)}" ${busy||status.busy||s.targetState!=='stopped'?'disabled':''}`)}</div></div><p class="smalltext spaced">${b.enabled===false?'Disabled':'Enabled'} · ignore ${b.ignoreCount||0} hits · ${b.observedHits||0} observed stops${b.watchMode?' · '+esc(b.watchMode)+' / '+b.width+' bytes':''}</p></div>`).join('')}`:''}</div></section><section class="panel spaced"><div class="panel-head"><h2>Preserved debugger snapshots</h2>${tag(records().length)}</div><div class="panel-body stack">${records().map(r=>`<div class="row between wrap"><div><strong>${esc(r.label)}</strong><p class="muted smalltext">${esc(r.status)} · ${esc(r.createdAt)} · ${r.dumpEvidenceIds.length} memory artifacts</p></div><div class="row">${button('Review snapshot','debug-review','small','',`data-id="${r.id}"`)}${button('Evidence','evidence-detail','small','',`data-id="${r.evidenceId}"`)}</div></div>`).join('')||'<p class="muted">Preserve a live snapshot or import a portable debugger session.</p>'}</div></section></div>`;}
 async function refresh(quiet=false){try{status=await request('debug/status');lastReported=new Date().toLocaleTimeString();message='';const p=ui.project();if(!status.sessions.some(s=>s.id===selected&&s.projectId===p?.id&&s.deviceId===p?.deviceId))selected=status.sessions.find(s=>s.projectId===p?.id&&s.deviceId===p?.deviceId)?.id||'';}catch(e){status=null;message=e.message;}if(quiet){const el=document.querySelector('#debug-live');if(el&&!document.querySelector('dialog[open]')){const focus=document.activeElement,action=focus?.dataset.action,id=focus?.dataset.id;el.outerHTML=view();wire();if(action)for(const b of document.querySelectorAll('#debug-live [data-action]'))if(b.dataset.action===action&&b.dataset.id===id)b.focus({preventScroll:true});}}else ui.render();}
 function attach(){const p=ui.project(),d=p.devices.find(d=>d.id===p.deviceId);showDialog('Attach debugger',`<div class="form-grid">${field('Session label','label',d.name+' · debug','text',true)}<label class="field full">Operator profile<select name="profileId" required>${options()}</select></label>${area('Measured wiring, voltage, probe identity & device state','conditions','')}<label class="field full"><span><input type="checkbox" name="ack" required> I reviewed this profile and the electrical connection; attach may halt or reset the target.</span></label></div><p class="notice spaced">Target scripts are supplied by your installed OpenOCD. PROBE issues no reset or flash command. CMSIS-DAP, J-Link and ST-Link / STM32F407VG profiles are unverified candidates.</p>`,async data=>{if(ui.project()!==p||p.deviceId!==d.id)throw Error('Project/device changed.');busy=true;try{const s=await request('debug/attach','POST',{projectId:p.id,deviceId:d.id,label:data.get('label'),profileId:data.get('profileId'),conditions:data.get('conditions'),deviceContext:JSON.stringify({model:d.model,firmware:d.firmware,hw:d.hw,serialSessions:p.sessions.filter(x=>x.deviceId===d.id).map(x=>x.id)}),acknowledge:data.has('ack')});selected=s.session.id;}finally{busy=false;await refresh();}},'Attach');}
 async function operate(op,input={}){const s=current();if(!s)throw Error('Select a session.');busy=true;try{await request('debug/sessions/'+s.id+'/operate','POST',{op,...input});message='Completed: '+op;}finally{busy=false;await refresh();}}
 function operation(op){if(['halt','resume','step','detach'].includes(op)){showDialog('Confirm '+op,`<p class="help-copy">${esc(({halt:'Halt target execution. This can interrupt normal device operation.',resume:'Resume target execution. Breakpoints may stop it again.',step:'Execute one machine instruction from the current stopped state.',detach:'Detach from the target. Detach can resume execution; its final execution state will be unknown.'})[op])}</p>`,()=>operate(op,{acknowledge:true}),'Execute '+op);return;}
 if(['memory','breakpoint','watchpoint'].includes(op)){const s=current();showDialog(op==='memory'?'Read memory':'Set hardware '+op,`<div class="form-grid">${field('Address (hex or decimal)','address',s.profile.regions[0]?'0x'+s.profile.regions[0].start.toString(16):'')}${op==='memory'?field('Length in bytes (≤1 MiB)','length',256,'number'):op==='watchpoint'?'<label class="field">Watch mode<select name="watchMode"><option>access</option><option>read</option><option>write</option></select></label><label class="field">Width in bytes<select name="width"><option>1</option><option>2</option><option selected>4</option></select></label>':''}</div><p class="notice spaced">Only declared flash/RAM regions are accessible; MMIO is excluded. Watchpoints cover an aligned 1, 2 or 4-byte value. Software fallback is rejected. Hardware slots are limited.</p><pre class="code-preview spaced">${esc(s.profile.regions.map(r=>r.name+': 0x'+r.start.toString(16)+' + '+r.length+' bytes').join('\n'))}</pre>`,data=>operate(op,{address:data.get('address'),length:Number(data.get('length')),...(op==='watchpoint'?{width:Number(data.get('width')),watchMode:data.get('watchMode')}:{})}),'Apply');return;}
 if(op==='symbols'){ui.pick('.elf',async file=>{if(file.size>8*1048576)throw Error('ELF symbols must be at most 8 MiB.');await operate(op,{name:file.name,dataBase64:encode64(new Uint8Array(await file.arrayBuffer()))});});return;}return operate(op);}
 async function preserve(input){const p=ui.project(),deviceId=p.deviceId,e=await validateDebugRecord(input),s=e.session;if((p.debugSessions?.length||0)>=100)throw Error('Project debugger snapshot limit reached.');if(records().some(r=>r.recordHash===e.recordHash))throw Error('This exact snapshot is already preserved.');const encoded=JSON.stringify(e),required=new TextEncoder().encode(encoded).length+s.dumps.reduce((n,d)=>n+d.size,0);if(p.evidence.reduce((n,x)=>n+x.size,0)+required>128*1048576)throw Error('Project evidence limit reached.');const record=await ui.evidenceFromFile(new File([encoded],s.id+'.debug.json',{type:'application/json'}),'Debugger snapshot',s.conditions,deviceId);record.tool=JSON.stringify(s.versions);record.conditions=s.conditions;record.source='Debugger record; imported hashes verified';const dumps=[];for(const d of s.dumps){const ev=await ui.evidenceFromFile(new File([decode64(d.dataBase64)],s.id+'-'+d.address+'.bin'),'Debugger memory',d.address,deviceId);ev.source='Memory read '+d.address;ev.conditions=s.conditions;dumps.push(ev);}if(ui.project()!==p||p.deviceId!==deviceId)throw Error('Project/device changed during preservation.');p.evidence.push(record,...dumps);p.debugSessions??=[];p.debugSessions.push({id:uid('debug'),deviceId,label:s.label,sessionId:s.id,recordHash:e.recordHash,status:s.status,createdAt:new Date().toISOString(),evidenceId:record.id,dumpEvidenceIds:dumps.map(e=>e.id)});ui.changed('Debugger snapshot and memory originals preserved. Inspect memory from FIRMGLASS.');}
 async function action(name,id){if(!name.startsWith('debug-'))return false;
 if(name==='debug-review'){const r=records().find(r=>r.id===id),s=JSON.parse(ui.rawText(ui.project().evidence.find(e=>e.id===r.evidenceId))).session;showDialog('Debugger snapshot',`<h3>${esc(s.label)}</h3><p class="notice spaced">${esc(s.status)} · preserved ${esc(r.createdAt)} · target ${esc(s.targetState)} at snapshot. Historical record; no live connection implied.</p><p class="scope-text spaced">${esc(s.conditions)}</p><h3 class="spaced">Registers</h3><pre class="code-preview">${esc(JSON.stringify(s.registers,null,2))}</pre><h3 class="spaced">Recorded events</h3><pre class="code-preview">${esc(JSON.stringify(s.events.slice(-50),null,2))}</pre><p class="muted smalltext">Latest 50 events shown. Full transcript and memory bytes remain in the original evidence JSON.</p>`);}else if(name==='debug-refresh')await refresh();else if(name==='debug-attach')attach();else if(name==='debug-op')await operation(id);else if(name==='debug-configure'){const b=current()?.breakpoints.find(b=>b.number===id);if(!b)throw Error('Hardware stop missing.');showDialog('Configure hardware stop #'+b.number,`<label class="field"><span><input name="enabled" type="checkbox" ${b.enabled!==false?'checked':''}> Enabled</span></label>${field('Ignore next N hits (0–1,000,000)','ignoreCount',b.ignoreCount||0,'number')}<p class="notice spaced">Changes apply to this session while stopped. Counts describe GDB behavior; observed stop counts include only notifications received by PROBE.</p>`,data=>operate('configure-breakpoint',{number:id,enabled:data.has('enabled'),ignoreCount:Number(data.get('ignoreCount'))}),'Apply');}else if(name==='debug-remove')await operate('remove-breakpoint',{number:id});else if(name==='debug-preserve')await preserve(await request('debug/sessions/'+current().id));else if(name==='debug-export')ui.download(current().id+'.debug.json',JSON.stringify(await request('debug/sessions/'+current().id),null,2));else if(name==='debug-import')ui.pick('.json',async f=>{if(f.size>32*1048576)throw Error('Choose a record under 32 MiB.');await preserve(JSON.parse(await f.text()));});return true;}
 function wire(){clearTimeout(pollTimer);const el=document.querySelector('#debug-session');if(el)el.onchange=()=>{selected=el.value;ui.render()};if(isCompanion()&&document.querySelector('#debug-live'))pollTimer=setTimeout(async()=>{if(!busy&&!document.hidden&&!document.querySelector('dialog[open]')&&document.querySelector('#debug-live'))await refresh(true);wire();},2000);}
 return {view,action,wire,init(){if(isCompanion())refresh();}};
}
